Here's a complete example of modern data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- DataRow: inline values for simple cases ---

    [TestMethod]
    [DataRow(10.00, 1, 10.00)]
    [DataRow(25.50, 2, 51.00)]
    [DataRow(0.00, 5, 0.00)]
    [DataRow(9.99, 0, 0.00, DisplayName = "Zero quantity returns zero")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples (preferred for complex/decimal data) ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
    ];

    // --- Edge cases / error handling ---

    [TestMethod]
    [DataRow(-1.0, 10)]
    [DataRow(100.0, -5)]
    [DataRow(100.0, 101)]
    public void ApplyDiscount_WithInvalidInputs_ThrowsArgumentException(
        double price, int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount((decimal)price, discountPercent));
    }
}
```

**Key points:**

- **`[DataRow]`** — best for simple inline primitives (`double` not `decimal`, since attributes need compile-time constants)
- **`[DynamicData]` with ValueTuples** — preferred for `decimal` values and complex scenarios; gives type safety (MSTest 3.7+)
- **`Assert.ThrowsExactly<T>`** — modern replacement for `[ExpectedException]`
- **Sealed class**, AAA pattern, descriptive `DisplayName` where helpful
- No `[DataTestMethod]` needed — `[TestMethod]` handles data rows in MSTest 3.x+
